// Normalize the RingCentral webhook (or any caller) into the
// {from, body, patient_hint} shape that the Python flow expects.
// Mirrors handle_inbound_file_request() input contract.
const payload = items[0].json || {};

// RingCentral inbound-SMS webhook nests the message under body.changes[0].
let from = payload.from || '';
let body = payload.body || '';
if (!from || !body) {
  const change = (((payload.body || {}).changes) || [])[0] || {};
  const msg = (change.newMessages || [])[0] || change || {};
  from = msg.from && msg.from.phoneNumber || from;
  body = msg.subject || msg.text || body;
}

return [{ json: {
  from: String(from || '').trim(),
  body: String(body || '').trim(),
  patient_hint: String(payload.patient_hint || '').trim()
}}];

// Happy path: the flow has minted a pending gate token.
// Hand back a 200 to the inbound webhook so RingCentral doesn't retry,
// AND surface the approval URL so the next step (staff notification)
// can include it. Per Q4 the staff approval channel is SMS DM to a
// designated RingCentral number — wire that as a second HTTP node
// calling /sms/send on the RC adapter, or call ringcentral_adapter via
// an Execute Command node.
const { token, approval_url, patient, stage } = items[0].json;
return [{ json: {
  ok: true,
  stage,
  token,
  approval_url,
  patient_name: (patient && patient.name) || null,
  staff_notice: `New file request from ${patient && patient.name || 'unknown'}: approve at ${approval_url}`
}}];

// Dead-letter / unhappy path. Two sub-cases:
//   1. /inbound returned ok=false (no patient match, no Drive folder,
//      no files) — recoverable, surface to staff via SMS so a human can
//      pick up the thread.
//   2. /inbound itself errored after retry — log + escalate.
// Q7/Q10: audit row + Q4-style SMS to the on-call staff number.
const payload = items[0].json || {};
const stage = payload.stage || 'unknown';
const reason = payload.reason || payload.message || 'unknown error';
const notice = `File request FAILED at stage=${stage}: ${reason}. Check /api/logs in Antigravity dashboard.`;
return [{ json: {
  ok: false,
  stage,
  reason,
  staff_notice: notice,
  needs_manual: true
}}];
